// Feature: autolog-vehicle-manager
// Property 11: Notification payload completeness
//
// For any reminder record, the notification payload generated by
// NotificationService contains the vehicle's nickname, the reminder type
// label, and either the formatted due date or the due odometer value.
//
// Validates: Requirements 11.2

import 'package:flutter_test/flutter_test.dart';
import 'package:kiri_check/kiri_check.dart';

import 'package:autolog/models/models.dart';
import 'package:autolog/utils/date_formatter.dart';

// ─────────────────────────────────────────────────────────────────────────────
// Payload builder (mirrors NotificationService._buildBody logic)
// ─────────────────────────────────────────────────────────────────────────────

String buildNotificationBody(Reminder reminder, String vehicleNickname) {
  final buffer = StringBuffer();
  buffer.write(vehicleNickname);
  buffer.write(' — ');
  buffer.write(_reminderTypeLabel(reminder.reminderType));

  if (reminder.dueDate != null) {
    buffer.write(': ');
    buffer.write(DateFormatter.format(reminder.dueDate!));
  } else if (reminder.dueOdometerKm != null) {
    buffer.write(' at ');
    buffer.write(reminder.dueOdometerKm!.toStringAsFixed(0));
    buffer.write(' km');
  }

  return buffer.toString();
}

String _reminderTypeLabel(ReminderType type) {
  switch (type) async {
    case ReminderType.insuranceExpiry:
      return 'Insurance Expiry';
    case ReminderType.pucExpiry:
      return 'PUC Expiry';
    case ReminderType.serviceDue:
      return 'Service Due';
    case ReminderType.odometerMilestone:
      return 'Odometer Milestone';
    case ReminderType.custom:
      return 'Reminder';
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Arbitraries
// ─────────────────────────────────────────────────────────────────────────────

Arbitrary<String> get _nonEmptyString =>
    string(minLength: 1, maxLength: 30).map((s) => s.isEmpty ? 'Car' : s);

Arbitrary<ReminderType> get _reminderType =>
    integer(min: 0, max: ReminderType.values.length - 1)
        .map((i) => ReminderType.values[i]);

Arbitrary<DateTime> get _futureDate => integer(min: 1, max: 3650).map(
      (days) => DateTime.now().add(Duration(days: days)),
    );

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

void main() {
  group('NotificationService — Property 11: payload completeness', () {
    test('body contains vehicle nickname for date-based reminders', () async {
      property(
        forAll(
          combine3(
            _nonEmptyString,
            _futureDate,
            _reminderType,
            (nickname, dueDate, type) => (nickname: nickname, dueDate: dueDate, type: type),
          ),
        ),
        (triple) async {
          final reminder = Reminder(
            id: 'r1',
            vehicleId: 'v1',
            title: 'Test Reminder',
            body: '',
            reminderType: triple.type,
            dueDate: triple.dueDate,
            isDismissed: false,
            createdAt: DateTime.now(),
          );

          final body = buildNotificationBody(reminder, triple.nickname);

          expect(body, contains(triple.nickname),
              reason: 'Body must contain vehicle nickname');
          expect(body, contains(_reminderTypeLabel(triple.type)),
              reason: 'Body must contain reminder type label');
          expect(body, contains(DateFormatter.format(triple.dueDate)),
              reason: 'Body must contain formatted due date');
        },
      );
    });

    test('body contains vehicle nickname for odometer-based reminders', () async {
      property(
        forAll(
          combine3(
            _nonEmptyString,
            float(min: 1000.0, max: 500_000.0, withNaN: false, withInfinities: false),
            _reminderType,
            (nickname, odo, type) => (nickname: nickname, odo: odo, type: type),
          ),
        ),
        (triple) async {
          final reminder = Reminder(
            id: 'r2',
            vehicleId: 'v1',
            title: 'Odometer Reminder',
            body: '',
            reminderType: triple.type,
            dueOdometerKm: triple.odo,
            isDismissed: false,
            createdAt: DateTime.now(),
          );

          final body = buildNotificationBody(reminder, triple.nickname);

          expect(body, contains(triple.nickname),
              reason: 'Body must contain vehicle nickname');
          expect(body, contains(_reminderTypeLabel(triple.type)),
              reason: 'Body must contain reminder type label');
          expect(body, contains('km'),
              reason: 'Body must contain odometer unit');
        },
      );
    });

    test('all ReminderType values produce non-empty labels', () {
      for (final type in ReminderType.values) {
        final label = _reminderTypeLabel(type);
        expect(label, isNotEmpty,
            reason: 'ReminderType.$type must have a non-empty label');
      }
    });

    test('known example: insurance expiry body format', () {
      final dueDate = DateTime(2025, 6, 15);
      final reminder = Reminder(
        id: 'r3',
        vehicleId: 'v1',
        title: 'Insurance Expiry',
        body: '',
        reminderType: ReminderType.insuranceExpiry,
        dueDate: dueDate,
        isDismissed: false,
        createdAt: DateTime.now(),
      );

      final body = buildNotificationBody(reminder, 'My Swift');
      expect(body, contains('My Swift'));
      expect(body, contains('Insurance Expiry'));
      expect(body, contains('15 Jun 2025'));
    });
  });
}
